#!/usr/bin/env python3
"""
PRD 验证工具
用于检查产品需求文档的质量和完整性
"""

import re
import sys
from typing import Dict, List, Set, Tuple
import argparse


class PRDValidator:
    """PRD验证器"""

    def __init__(self):
        self.issues = []
        self.checks = [
            self._check_vague_language,
            self._check_5w_elements,
            self._check_acceptance_criteria,
            self._check_metrics,
            self._check_user_stories,
            self._check_technical_feasibility,
            self._check_edge_cases
        ]

    def validate(self, prd_text: str) -> Dict:
        """验证PRD文本"""
        self.issues = []

        for check in self.checks:
            check(prd_text)

        return {
            'score': self._calculate_score(),
            'issues': self.issues,
            'summary': self._generate_summary()
        }

    def _check_vague_language(self, text: str):
        """检查模糊语言"""
        vague_patterns = [
            r'\b(高效|高性能|快速|稳定|安全|可靠|友好|易用|美观|好)\b',
            r'\b(提升|优化|改善|增强|完善)\b',
            r'应该|尽量|可能|大概|或许'
        ]

        for pattern in vague_patterns:
            matches = re.finditer(pattern, text, re.IGNORECASE)
            for match in matches:
                line_num = text[:match.start()].count('\n') + 1
                self.issues.append({
                    'type': 'vague_language',
                    'severity': 'high',
                    'line': line_num,
                    'message': f"发现模糊语言: '{match.group()}'，请使用具体指标",
                    'suggestion': "将模糊描述替换为具体指标，如'响应时间≤500ms'"
                })

    def _check_5w_elements(self, text: str):
        """检查5W元素完整性"""
        missing_5w = []

        # 检查Who
        if '用户角色' not in text and 'target user' not in text.lower():
            missing_5w.append('用户角色(Who)')

        # 检查What
        if '功能' not in text or '需求' not in text:
            missing_5w.append('功能内容(What)')

        # 检查When
        if '时间' not in text and '何时' not in text:
            missing_5w.append('时间条件(When)')

        # 检查Where
        if '场景' not in text and '位置' not in text:
            missing_5w.append('使用场景(Where)')

        # 检查How
        if '流程' not in text and '步骤' not in text:
            missing_5w.append('实现步骤(How)')

        if missing_5w:
            self.issues.append({
                'type': 'missing_5w',
                'severity': 'high',
                'line': 1,
                'message': f"缺少5W元素: {', '.join(missing_5w)}",
                'suggestion': "确保PRD包含完整的5W元素：Who/What/When/Where/How"
            })

    def _check_acceptance_criteria(self, text: str):
        """检查验收标准"""
        acceptance_indicators = ['验收标准', '测试用例', '成功标准']

        has_acceptance = any(indicator in text for indicator in acceptance_indicators)

        if not has_acceptance:
            self.issues.append({
                'type': 'missing_acceptance',
                'severity': 'medium',
                'line': 1,
                'message': "缺少验收标准",
                'suggestion': "为每个功能添加具体的验收标准和测试用例"
            })

        # 检查验收标准的可测试性
        if '验收标准' in text:
            acceptance_section = text.split('验收标准')[1] if '验收标准' in text else text
            if '应该' in acceptance_section or '可能' in acceptance_section:
                self.issues.append({
                    'type': 'uncertain_criteria',
                    'severity': 'medium',
                    'line': 1,
                    'message': "验收标准包含不确定表述",
                    'suggestion': "验收标准应使用确定、可测试的语言"
                })

    def _check_metrics(self, text: str):
        """检查指标"""
        metric_patterns = [
            r'<\s*[0-9]+\s*>',  # <数值>
            r'[0-9]+\s*%',      # 百分比
            r'[0-9]+\s*ms',     # 毫秒
            r'[0-9]+\s*并发',    # 并发数
        ]

        has_metrics = any(re.search(pattern, text) for pattern in metric_patterns)

        if not has_metrics:
            self.issues.append({
                'type': 'missing_metrics',
                'severity': 'high',
                'line': 1,
                'message': "缺少量化指标",
                'suggestion': "添加具体的成功指标，如'响应时间≤500ms'，'转化率≥5%'"
            })

    def _check_user_stories(self, text: str):
        """检查用户故事"""
        story_indicators = ['作为', '我想要', '以便']

        # 检查用户故事格式
        has_story_format = all(indicator in text for indicator in story_indicators)

        if not has_story_format:
            self.issues.append({
                'type': 'missing_user_story',
                'severity': 'medium',
                'line': 1,
                'message': "缺少标准用户故事",
                'suggestion': "使用'作为[用户]，我想要[功能]，以便[价值]'格式"
            })

    def _check_technical_feasibility(self, text: str):
        """检查技术可行性标识"""
        technical_terms = ['API', '数据库', '架构', '性能', '安全']

        has_technical = any(term in text for term in technical_terms)

        if not has_technical:
            self.issues.append({
                'type': 'missing_technical',
                'severity': 'low',
                'line': 1,
                'message': "缺少技术考虑",
                'suggestion': "添加技术可行性相关的考虑，如性能、安全、扩展性"
            })

    def _check_edge_cases(self, text: str):
        """检查边界条件"""
        edge_indicators = ['异常', '错误', '异常情况', '边界', '特殊情况', '限制']

        has_edge = any(indicator in text for indicator in edge_indicators)

        if not has_edge:
            self.issues.append({
                'type': 'missing_edge_cases',
                'severity': 'medium',
                'line': 1,
                'message': "缺少异常和边界情况处理",
                'suggestion': "添加异常处理和边界条件，如网络中断、数据错误等"
            })

    def _calculate_score(self) -> int:
        """计算质量分数"""
        if not self.issues:
            return 100

        severity_scores = {'high': 10, 'medium': 5, 'low': 1}
        total_deduction = sum(issue['severity'] * severity_scores[issue['type']]
                            for issue in self.issues)

        return max(0, 100 - total_deduction)

    def _generate_summary(self) -> str:
        """生成验证摘要"""
        if not self.issues:
            return "✅ PRD质量优秀，没有发现问题！"

        summary = []
        summary.append(f"📊 PRD质量评分: {self._calculate_score()}/100")

        # 按严重程度分类
        high_issues = [i for i in self.issues if i['severity'] == 'high']
        medium_issues = [i for i in self.issues if i['severity'] == 'medium']
        low_issues = [i for i in self.issues if i['severity'] == 'low']

        if high_issues:
            summary.append(f"🔴 高优先级问题: {len(high_issues)}个")
        if medium_issues:
            summary.append(f"🟡 中优先级问题: {len(medium_issues)}个")
        if low_issues:
            summary.append(f"🟢 低优先级问题: {len(low_issues)}个")

        return "\n".join(summary)


def read_file(file_path: str) -> str:
    """读取文件"""
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            return f.read()
    except Exception as e:
        print(f"❌ 读取文件失败: {e}")
        sys.exit(1)


def main():
    parser = argparse.ArgumentParser(description='PRD质量验证工具')
    parser.add_argument('file', help='PRD文件路径')
    parser.add_argument('--output', '-o', help='输出报告文件路径')

    args = parser.parse_args()

    # 读取PRD文件
    prd_text = read_file(args.file)

    # 验证PRD
    validator = PRDValidator()
    result = validator.validate(prd_text)

    # 输出结果
    print("=" * 50)
    print("PRD质量验证报告")
    print("=" * 50)
    print(result['summary'])
    print()

    if result['issues']:
        print("📋 发现的问题:")
        for i, issue in enumerate(result['issues'], 1):
            print(f"{i}. [{issue['severity'].upper()}] {issue['message']}")
            print(f"   建议: {issue['suggestion']}")
            print()

    # 保存报告
    if args.output:
        with open(args.output, 'w', encoding='utf-8') as f:
            f.write(f"PRD验证报告\n{'='*50}\n")
            f.write(f"质量评分: {result['score']}/100\n\n")
            f.write(result['summary'] + "\n\n")

            if result['issues']:
                f.write("发现的问题:\n")
                for issue in result['issues']:
                    f.write(f"- [{issue['severity'].upper()}] {issue['message']}\n")
                    f.write(f"  建议: {issue['suggestion']}\n\n")

        print(f"📄 报告已保存到: {args.output}")


if __name__ == '__main__':
    main()

